    44	import type { OriginClient, OriginResponse } from './broker.js';
    45	
    46	/** The port the HTTP server binds. Defaults to 8787 for a small VPS. */
    47	export const PORT = Number(process.env.PORT ?? 8787);
    48	
    49	/** Host/interface to bind. Default: all interfaces (Caddy fronts it in prod). */
    50	export const HOST = process.env.HOST ?? '0.0.0.0';
    51	
    52	/**
    53	 * A metered origin client. Two modes:
    54	 *
    55	 *  - `ORIGIN_URL` unset (default): a self-fulfilling origin. Every settled
    56	 *    request returns HTTP 200 with synthetic body + no license. This lets the
    57	 *    broker run `fulfilled` end-to-end with no real origin behind it — the
    58	 *    whole metered path (quote → authorize → settle → record) executes.
    59	 *  - `ORIGIN_URL` set: the settled request is proxied to that URL over HTTP.
    60	 *    This is the path to a real metered origin (self 402, x402, Cloudflare PPC).
    61	 */
    62	export class MeteredOrigin implements OriginClient {
    63	  private readonly target?: UrlString;
    64	
    65	  constructor(target?: UrlString) {
    66	    this.target = target;
    67	  }
    68	
    69	  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    70	    if (this.target) {
    71	      const res = await fetch(this.target, {
    72	        method: req.method,
    73	        headers: req.headers,
    74	      });
    75	      return {
    76	        httpStatus: res.status,
    77	        headers: headerRecord(res),
    78	        body: await res.text(),
    79	      };
    80	    }
    81	    // Self origin: nothing behind the broker, so report satisfied.
    82	    return {
    83	      httpStatus: 200,
    84	      headers: { 'content-type': 'text/plain; charset=utf-8' },
    85	      body: 'metered content from a self-hosted origin (ORIGIN_URL unset)',
    86	    };
    87	  }
