   114	/** Parse budget policy from env, overriding just the per-call ceiling. */
   115	function buildPolicy(): BudgetPolicy {
   116	  const policy: BudgetPolicy = { ...defaultPolicy };
   117	  const ceiling = process.env.PER_CALL_CEILING_MICROS;
   118	  if (ceiling && Number.isFinite(Number(ceiling))) {
   119	    policy.perCallCeilingMicros = Number(ceiling);
