   124	/**
   125	 * Build the full broker from env. Every collaborator is injected exactly as the
   126	 * broker unit tests do, so the wiring here is the same one the test proves.
   127	 *
   128	 * Returns the broker alongside the small bits of state the HTTP layer needs to
   129	 * shape responses (the audit ledger, the origin mode, whether identity is on)
   130	 * so `createApp` never reaches into broker internals.
   131	 */
   132	export function buildBroker(): {
   133	  broker: Broker;
   134	  ledger: AuditLedger;
   135	  origin: MeteredOrigin;
   136	  originTarget?: UrlString;
   137	  identityOn: boolean;
