   164	/** Read the whole request body as text. */
   165	async function readBody(req: IncomingMessage): Promise<string> {
   166	  const chunks: Buffer[] = [];
   167	  for await (const chunk of req) chunks.push(chunk as Buffer);
   168	  return Buffer.concat(chunks).toString('utf-8');
