   171	/** A plain object from an HTTP response's headers (Node Headers → record). */
   172	function headerRecord(res: Response): HeaderRecord {
   173	  const out: HeaderRecord = {};
   174	  res.headers.forEach((v, k) => {
   175	    out[k] = v;
   176	  });
   177	  return out;
   178	}
