   180	/** Send a JSON response with status and Content-Type. */
   181	function sendJson(res: ServerResponse, status: number, body: unknown): void {
   182	  const raw = JSON.stringify(body);
   183	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
   184	  res.end(raw);
   185	}
