   202	/**
   203	 * Handle `POST /fetch`. Decodes the request, runs `Broker.fetch`, and maps the
   204	 * broker's terminal outcome to a JSON response. Every broker terminal class is
   205	 * one of {fulfilled, blocked, payment-required, token-rejected}; there is no
   206	 * generic `error` status.
   207	 */
   208	export async function handleFetch(
   209	  broker: Broker,
   210	  raw: string,
   211	): Promise<{ status: number; body: unknown }> {
   212	  let req: FetchRequest;
   213	  try {
   214	    req = JSON.parse(raw) as FetchRequest;
   215	  } catch {
   216	    return { status: 400, body: { error: 'invalid JSON body' } };
   217	  }
   218	  if (!req || typeof req.url !== 'string') {
   219	    return { status: 400, body: { error: "missing required string field 'url'" } };
   220	  }
   221	
   222	  const outcome = await broker.fetch({
   223	    url: req.url,
   224	    fetchId: req.fetchId,
   225	    tenantId: req.tenantId,
   226	    headers: req.headers as HeaderRecord | undefined,
   227	  });
