   229	  // A fulfilled metered fetch succeeds (200). Otherwise map the terminal class
   230	  // to an HTTP status agents can branch on: payment-required (402) for any
   231	  // metered-charge gate, and 403 for the rest (blocked, token-rejected, error).
   232	  const status =
   233	    outcome.status === 'fulfilled'
   234	      ? 200
   235	      : outcome.failureClass === 'payment-required'
   236	        ? 402
   237	        : 403;
   238	  return { status, body: outcome };
   239	}
