   295	/**
   296	 * Create (but do not start) the HTTP server. Exposed so the test can bind an
   297	 * ephemeral port without opening a real socket in the module.
   298	 */
   299	export function createApp(cfg: ServerConfig): Server {
   300	  const { ledger, origin, originTarget, broker } = cfg;
   301	
   302	  const server = createServer((req, res) => {
   303	    const url = req.url ?? '/';
   304	    const method = req.method ?? 'GET';
   305	
   306	    if (method === 'GET' && url === '/health') {
   307	      const { status, body } = handleHealth();
