   312	      return void sendJson(res, status, body);
   313	    }
   314	    if (method === 'GET' && url === '/audit/dashboard') {
   315	      const { status, body } = handleAuditDashboard(ledger);
   316	      return void sendJson(res, status, body);
   317	    }
   318	    if (method === 'GET' && url === '/audit') {
   319	      const { status, body } = handleAudit(ledger);
   320	      return void sendJson(res, status, body);
   321	    }
   322	    if (method === 'POST' && url === '/fetch') {
   323	      void (async () => {
   324	        try {
   325	          const raw = await readBody(req);
   326	          const { status, body } = await handleFetch(broker, raw);
