   350	  // Log the effective origin mode (self-origin or proxied) at boot.
   351	  server.on('listening', () => {
   352	    // eslint-disable-next-line no-console
   353	    console.log(
   354	      `metered-web-broker listening on http://${HOST}:${PORT}` +
   355	        (originTarget ? `  (origin → ${originTarget})` : '  (self origin)'),
   356	    );
   357	  });
