{"path": "packages/conformance/src/cli.ts", "start_line": 1, "end_line": 34, "total_lines": 34, "content": "     1	import { readFileSync } from 'node:fs';
     2	import { report, run } from './run.js';
     3	import type { ContractCard, ConformanceResult } from './types.js';
     4	
     5	/**
     6	 * The entry point CI invokes:
     7	 *
     8	 *   tsx packages/conformance/src/cli.ts <fixturePath> <contractName>
     9	 *
    10	 * Reads + JSON-parses the fixture, resolves the validators by contractName,
    11	 * runs them, reports, and exits 0 on full pass / 1 on any failure.
    12	 */
    13	function main(argv: string[]): number {
    14	  const [fixturePath, contractName] = argv;
    15	
    16	  if (!fixturePath || !contractName) {
    17	    console.error('usage: conformance <fixturePath> <contractName>');
    18	    return 1;
    19	  }
    20	
    21	  let card: ContractCard;
    22	  try {
    23	    card = JSON.parse(readFileSync(fixturePath, 'utf8')) as ContractCard;
    24	  } catch (cause) {
    25	    console.error(`failed to read fixture "${fixturePath}": ${(cause as Error).message}`);
    26	    return 1;
    27	  }
    28	
    29	  const result: ConformanceResult = run(card, contractName);
    30	  report(result);
    31	  return result.pass ? 0 : 1;
    32	}
    33	
    34	process.exit(main(process.argv.slice(2)));"}

