   259	    if (this.consumed.has(m.nonce)) {
   260	      return { valid: false, reason: 'replayed-proof' };
   261	    }
   262	    return { valid: true };
   263	  }
   264	
   265	  /**
   266	   * The payment commit. Verifies, rejects a replayed nonce (throwing
   267	   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   268	   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   269	   */
   270	  settle(m: PaymentMandate): RailSettlement {
   271	    const v = this.verify(m);
   272	    if (!v.valid) {
   273	      throw new RailError(
   274	        `settlement rejected: ${v.reason ?? 'unknown'}`,
   275	        'RAIL_SETTLE',
   276	        undefined,
   277	        false,
   278	      );
   279	    }
   280	    const settledAt = this.clock.now();
   281	    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
   282	    const receipt: SettlementReceipt = {
   283	      settlementRef,
   284	      origin: m.origin,
   285	      url: m.url,
   286	      amountMicros: m.amountMicros,
   287	      currency: m.currency,
   288	      nonce: m.nonce,
   289	      issuedAt: m.issuedAt,
   290	      settledAt,
   291	    };
   292	    const prevSig = this.ledgerRows.length > 0 ? this.ledgerRows[this.ledgerRows.length - 1]!.signature : 'genesis';
   293	    const seq = this.ledgerRows.length + 1;
   294	    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
   295	    const signature = signBytes(this.key, chain);
   296	    this.ledgerRows.push({ seq, receipt, signedAt: settledAt, signature });
   297	    this.consumed.add(m.nonce);
   298	    return {
   299	      rail: 'self402',
   300	      settlementRef,
   301	      amountMicros: m.amountMicros,
   302	      currency: m.currency,
   303	      settledAt,
   304	    };
   305	  }
   306	
   307	  /** The current settlement ledger (a copy) — surfaced on the audit view. */
   308	  ledger(): LedgerRecord[] {
   309	    return this.ledgerRows.map((r) => ({ ...r, receipt: { ...r.receipt } }));
   310	  }
   311	
   312	  /** How many distinct nonces have been settled (== ledger length). */
   313	  settledCount(): number {
   314	    return this.ledgerRows.length;
   315	  }
   316	}
   317	
   318	/**
   319	 * A `PaymentRail` backed by a settlement backend (in-process
   320	 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
   321	 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
   322	 * — the broker only sees `quote/authorize/settle`.
   323	 */
   324	export class SelfHosted402Rail implements PaymentRail {
   325	  readonly id = 'self402';
   326	
   327	  constructor(
   328	    private readonly backend: SettlementBackend,
   329	    private readonly key: SettlementKey,
   330	    private readonly opts: {
   331	      priceMicros: Micros;
   332	      currency?: string;
   333	      clock?: Clock;
   334	      origin?: string;
   335	    },
   336	  ) {}
   337	
   338	  async quote(_req: PaymentRequest): Promise<Quote> {
   339	    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
   340	    return {
   341	      unitsMicros: this.opts.priceMicros,
   342	      currency: this.opts.currency ?? 'USD',
   343	      rail: this.id,
   344	      settlement: 'immediate',
   345	      expiresAt: new Date(nowMs + 60_000).toISOString(),
   346	    };
   347	  }
   348	
   349	  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   350	    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
   351	    const mandate = buildMandate({
   352	      origin,
   353	      url: String(req.url),
   354	      amountMicros: quote.unitsMicros,
   355	      currency: this.opts.currency ?? 'USD',
   356	      recipient: this.key.keyId,
   357	      clock: this.opts.clock ?? systemClock,
   358	      key: this.key,
   359	    });
   360	    const xPayment = b64url(Buffer.from(JSON.stringify(mandate), 'utf8'));
   361	    return {
   362	      scheme: this.id,
   363	      payload: JSON.stringify(mandate),
   364	      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
   365	    };
   366	  }
   367	
   368	  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   369	    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
   370	    if (mandate.url !== String(req.url)) {
   371	      throw new RailError('settlement mandate does not match the request', 'RAIL_SETTLE');
   372	    }
   373	    return this.backend.settle(mandate);
   374	  }
   375	}
   376	
   377	/**
   378	 * The backend contract the rail commits through: the settle commit, a pure
   379	 * `isValidMandate` cross-check (an origin can use it), and the key id the
   380	 * receipt references.
   381	 */
   382	export interface SettlementBackend {
   383	  settle(mandate: PaymentMandate): Promise<RailSettlement>;
   384	  isValidMandate(mandate: PaymentMandate): boolean;
   385	  readonly keyId: string;
   386	}
   387	
   388	// `SettlementServer` is synchronous at its crypto core, but the rail is async,
   389	// so wrap the commit in a resolved promise to keep one uniform shape.
   390	function ok(s: RailSettlement): Promise<RailSettlement> {
   391	  return Promise.resolve(s);
   392	}
   393	
   394	export class InProcessSettlementBackend implements SettlementBackend {
   395	  readonly keyId: string;
   396	
   397	  constructor(private readonly server: SettlementServer) {
   398	    // `keyId` reads the parameter property, so it must be initialized inside
   399	    // the constructor body — a field initializer runs *before* parameter
   400	    // properties are assigned (TS2729: used before initialization).
   401	    this.keyId = this.server.key.keyId;
   402	  }
   403	
   404	  settle(mandate: PaymentMandate): Promise<RailSettlement> {
   405	    return ok(this.server.settle(mandate));
   406	  }
   407	  isValidMandate(mandate: PaymentMandate): boolean {
   408	    return this.server.isValidMandate(mandate);
   409	  }
   410	}
   411	
   412	/**
   413	 * Convenience: a `SelfHosted402Rail` over an in-process `SettlementServer`,
   414	 * sharing its key. This is the default wiring in `packages/gateway/src/server.ts`.
   415	 */
   416	export function makeSelf402Rail(
   417	  server: SettlementServer,
   418	  options: { priceMicros: Micros; currency?: string; clock?: Clock; origin?: string } = {
   419	    priceMicros: 5000,
   420	  },
   421	): SelfHosted402Rail {
   422	  return new SelfHosted402Rail(
   423	    new InProcessSettlementBackend(server),
   424	    server.key,
   425	    options,
   426	  );
   427	}
   428	
   429	/** The decoded wire payload carried in the `x-payment` header. */
   430	export interface XPayment {
   431	  type: string;
   432	  mandate: PaymentMandate;
   433	}
   434	
   435	/** Encode the proof header value (`x-payment`). */
   436	export function encodeXPayment(mandate: PaymentMandate): string {
   437	  return b64url(
   438	    Buffer.from(
   439	      JSON.stringify({ type: PAYMENT_MANDATE_TYPE, mandate } satisfies XPayment),
   440	      'utf8',
   441	    ),
   442	  );
   443	}
   444	
   445	/** Decode the proof header value; throws on malformed input. */
   446	export function decodeXPayment(value: string): PaymentMandate {
   447	  let raw: string;
   448	  try {
   449	    // Base64url must round-trip exactly; if it does not, the header is
   450	    // malformed (not merely un-JSON). Reject it as such.
   451	    const bytes = fromB64url(value);
   452	    if (b64url(bytes) !== value) {
   453	      throw new Error('not valid base64url');
   454	    }
   455	    raw = Buffer.from(bytes).toString('utf8');
   456	  } catch (cause) {
   457	    throw new RailError('malformed x-payment header', 'SETTLEMENT_DECODE', cause);
   458	  }
   459	  let parsed: XPayment;
   460	  try {
   461	    parsed = JSON.parse(raw) as XPayment;
   462	  } catch (cause) {
   463	    throw new RailError('x-payment is not JSON', 'SETTLEMENT_DECODE', cause);
   464	  }
   465	  if (!parsed || parsed.type !== PAYMENT_MANDATE_TYPE || !parsed.mandate) {
   466	    throw new RailError('unknown x-payment shape', 'SETTLEMENT_DECODE');
   467	  }
   468	  return parsed.mandate;
   469	}
   470	
   471	/**
   472	 * A `SettlementBackend` that commits against a *remote* settlement service over
   473	 * HTTP (standalone `SettlementHttpServer`). Lets the backend run on its own
   474	 * host while the rail stays identical. `isValidMandate` is a local signature
   475	 * check (the remote cannot see the broker's key) plus a freshness read.
   476	 */
   477	export class HttpSettlementClient implements SettlementBackend {
   478	  constructor(
   479	    private readonly url: string,
   480	    private readonly key: SettlementKey,
   481	  ) {}
   482	
   483	  get keyId(): string {
   484	    return this.key.keyId;
   485	  }
   486	
   487	  isValidMandate(m: PaymentMandate): boolean {
   488	    return verifyMandate(m, this.key, { nowMs: Date.now() }).valid;
   489	  }
   490	
   491	  async settle(m: PaymentMandate): Promise<RailSettlement> {
   492	    const res = await fetch(`${this.url.replace(/\/$/, '')}/settle`, {
   493	      method: 'POST',
   494	      headers: { 'content-type': 'application/json' },
   495	      body: JSON.stringify(m),
   496	    });
   497	    if (!res.ok) {
   498	      // A settlement rejection (e.g. replayed nonce) is the payment rail
   499	      // "still demanding payment" — surface it as a non-retryable settle fault.
   500	      let reason: string | undefined;
   501	      try {
   502	        const json = (await res.json()) as { reason?: string };
   503	        reason = json.reason;
   504	      } catch {
   505	        /* ignore */
   506	      }
   507	      throw new RailError(
   508	        `settlement service returned ${res.status}${reason ? `: ${reason}` : ''}`,
   509	        'RAIL_SETTLE',
   510	        undefined,
   511	        reason === 'replayed-proof',
   512	      );
   513	    }
   514	    const body = (await res.json()) as RailSettlement & { receipt: SettlementReceipt };
   515	    if (!body.settlementRef) {
   516	      throw new RailError('settlement service returned no ref', 'RAIL_SETTLE');
   517	    }
   518	    return body;
   519	  }
   520	}
   521	
   522	// --- Standalone settlement HTTP service -----------------------------------
   523	
   524	/**
   525	 * A tiny, dependency-free HTTP surface over a `SettlementServer`. The
   526	 * settlement service is its own process on the backend host; this exposes just
   527	 * what a `HttpSettlementClient` (and any independent auditor) needs:
   528	 *
   529	 *   GET  /health        -> liveness, with backend keyId and ledger depth
   530	 *   POST /accept         -> verify a mandate's signature (non-consuming)
   531	 *   POST /settle         -> the payment commit (consumes the nonce)
   532	 *   GET  /ledger         -> the chained, tamper-evident receipt ledger
   533	 *
   534	 * The router (a `RouteTable`) is pure so it can be unit-tested by dispatching
   535	 * decoded requests; the server just funnels a raw request through it. Tests bind
   536	 * this to a `listen(0)` socket (no fixed port), so the routing is covered
   537	 * without opening any socket.
   538	 */
   539	interface Decoded {
   540	  pathname: string;
   541	  body?: unknown;
   542	}
   543	
   544	type Result = { status: number; body: unknown };
   545	
   546	type Handle = (req: Decoded) => Promise<Result> | Result;
   547	
   548	class RouteTable {
   549	  private readonly routes: { method: 'GET' | 'POST'; pattern: RegExp; handle: Handle }[] = [];
   550	
   551	  add(method: 'GET' | 'POST', pattern: RegExp, handle: Handle): void {
   552	    this.routes.push({ method, pattern, handle });
   553	  }
   554	
   555	  async dispatch(
   556	    method: 'GET' | 'POST',
   557	    pathname: string,
   558	    raw: string,
   559	  ): Promise<Result> {
   560	    const decoded: Decoded = {
   561	      pathname,
   562	      body: method === 'POST' ? decodeBody(raw) : undefined,
   563	    };
   564	    for (const r of this.routes) {
   565	      if (r.method !== method || !r.pattern.test(pathname)) continue;
   566	      return r.handle(decoded);
   567	    }
   568	    return {
   569	      status: 404,
   570	      body: { error: 'not-found', detail: `${method} ${pathname} matches no route` },
   571	    };
   572	  }
   573	}
   574	
   575	function decodeBody(raw: string): unknown {
   576	  if (!raw || raw.trim().length === 0) return {};
   577	  return JSON.parse(raw) as unknown;
   578	}
   579	
   580	export class SettlementHttpServer {
   581	  readonly table = new RouteTable();
   582	
   583	  constructor(private readonly server: SettlementServer) {
   584	    // Liveness: is the backend up, and what is its depth of settlements?
   585	    this.table.add('GET', /^\/health$/, () => ({
   586	      status: 200,
   587	      body: {
   588	        status: 'ok',
   589	        keyId: this.server.key.keyId,
   590	        settled: this.server.settledCount(),
   591	        ledgerDepth: this.server.ledger().length,
   592	      },
   593	    }));
   594	
   595	    // Accept: verify a mandate's signature without consuming its nonce.
   596	    // This is what an origin would call before releasing content.
   597	    this.table.add('POST', /^\/accept$/, (req) => {
   598	      let m: PaymentMandate;
   599	      try {
   600	        m = req.body as PaymentMandate;
   601	      } catch {
   602	        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
   603	      }
   604	      const valid = this.server.isValidMandate(m);
   605	      return {
   606	        status: valid ? 200 : 402,
   607	        body: {
   608	          valid,
   609	          keyId: this.server.key.keyId,
   610	        },
   611	      };
   612	    });
   613	
   614	    // Settle: the payment commit. Verifies, enforces replay protection,
   615	    // records a chained receipt, and returns it.
   616	    this.table.add('POST', /^\/settle$/, (req) => {
   617	      let m: PaymentMandate;
   618	      try {
   619	        m = req.body as PaymentMandate;
   620	      } catch {
   621	        return { status: 400, body: { error: 'bad-request', detail: 'missing mandate' } };
   622	      }
   623	      try {
   624	        const settlement = this.server.settle(m);
   625	        return {
   626	          status: 200,
   627	          body: {
   628	            rail: settlement.rail,
   629	            settlementRef: settlement.settlementRef,
   630	            amountMicros: settlement.amountMicros,
   631	            currency: settlement.currency,
   632	            settledAt: settlement.settledAt,
   633	          },
   634	        };
   635	      } catch (cause) {
   636	        // A non-retryable reject (e.g. replayed nonce) is the backend "still
   637	        // demanding payment" — return 402 so the client maps it to a
   638	        // payment-required outcome.
   639	        if (isRailError(cause) && cause.retryable === false) {
   640	          return {
   641	            status: 402,
   642	            body: { error: 'settlement-rejected', reason: reasonOf(cause) },
   643	          };
   644	        }
   645	        return { status: 500, body: { error: 'internal', detail: 'settlement error' } };
   646	      }
   647	    });
   648	
   649	    // Ledger: the full, chained, tamper-evident receipt ledger.
   650	    this.table.add('GET', /^\/ledger$/, () => ({
   651	      status: 200,
   652	      body: {
   653	        keyId: this.server.key.keyId,
   654	        count: this.server.ledger().length,
   655	        records: this.server.ledger(),
   656	      },
   657	    }));
   658	  }
   659	
   660	  /** The backend's key id (for the standalone health endpoint / wiring). */
   661	  get keyId(): string {
   662	    return this.server.key.keyId;
   663	  }
   664	
   665	  /**
   666	   * Dispatch a raw request through the router. `pathname` should be path only
   667	   * (no query string). This is the seam tested by the HTTP integration test.
   668	   */
   669	  async dispatch(
   670	    method: 'GET' | 'POST',
   671	    pathname: string,
   672	    raw = '',
   673	  ): Promise<Result> {
   674	    return this.table.dispatch(method, pathname, raw);
   675	  }
   676	}
   677	
   678	function isRailError(e: unknown): e is RailError {
   679	  return e instanceof RailError;
   680	}
   681	
   682	function reasonOf(e: RailError): string {
   683	  // The settle fault carries the backend's rejection reason in its message.
   684	  const m = /\s*:\s*([a-z-]+)$/.exec(e.message);
   685	  return m ? m[1] ?? 'settlement-rejected' : 'settlement-rejected';
   686	}
   687	"}

