{"path": "packages/gateway/src/metered-origin.test.ts", "content": "/**
 * P1 + P2: the load-bearing metered path, proven on REAL bytes.
 *
 * Not a stubbed rail, not a dummy origin. This wires the real
 * `SelfHosted402Rail` over an in-process `SettlementServer` (real Ed25519,
 * replay/nonce-guarded settlement — see `packages/rails/src/selfsettle.ts`)
 * behind a REAL metered origin that verifies the broker's signed payment
 * mandate against the settlement key's public part and enforces origin-side
 * replay protection, exactly as a real self-402 / x402 / Cloudflare-PPC origin
 * would. The broker only ever sees the opaque `quote → authorize → settle`
 * interface and a real origin that releases only after a real, verified 402
 * proof.
 *
 * P2: a fulfilled fetch is only `finality: 'final'` when the ledger as a whole
 * reconciles clean (`reconcile().ok === true`) — the settlement is proven, not
 * merely attempted.
 *
 * The metered pipeline (broker.ts) is: rail.quote → rail.authorize →
 * rail.settle → origin.fetch(...). Because the rail *always* signs a real
 * mandate, a real origin that releases on a valid proof yields the full
 * 402 → settle → 200 round trip; an origin that rejects a forged/replayed
 * proof yields the 402 leg on the same wire form.
 */

import { describe, expect, it } from 'vitest';
import { createServer, request, type AddressInfo } from 'node:http';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { AuditLedger, reconcile } from '@mwb/audit';
import {
  SelfHosted402Rail,
  SettlementServer,
  makeSelf402Rail,
  makeSettlementKey,
  verifyMandate,
  encodeXPayment,
  decodeXPayment,
} from '@mwb/rails';
import type { PaymentMandate, SettlementKey } from '@mwb/rails';
import { makeFetchId, systemClock, type Clock, type PaymentRequest, type UrlString } from '@mwb/core';
import { Broker, type OriginClient, type OriginResponse } from '@mwb/gateway';
import { handleFetch } from './server.js';

const clock: Clock = systemClock;
const PRICE = 5000;
const CONTENT_URL = 'https://api.example.com/data' as UrlString;

/**
 * A real metered origin. It never sees the broker's private key: it decodes
 * the broker's `x-payment` proof, verifies the Ed25519 signature + acceptance
 * window against the settlement key's public part, and refuses to release
 * content twice for the same proof (origin-side replay protection). A forged,
 * tampered, or replayed proof is answered HTTP 402 — exactly what a real
 * metered origin does.
 */
class RealMeteredOrigin implements OriginClient {
  private readonly key: SettlementKey;
  private readonly consumedNonce = new Set<string>();

  constructor(key: SettlementKey) {
    this.key = key;
  }

  async fetch(req: PaymentRequest): Promise<OriginResponse> {
    const header = req.headers['x-payment'];

    // No proof presented at all → a real metered origin demands payment.
    if (!header || typeof header !== 'string') {
      return { httpStatus: 402, headers: {}, body: 'payment required: no proof' };
    }

    let mandate: PaymentMandate;
    try {
      mandate = decodeXPayment(header); // throws on a malformed wire form
    } catch {
      return { httpStatus: 402, headers: {}, body: 'payment required: malformed proof' };
    }

    // Real Ed25519 verification against the settlement key's public part,
    // plus acceptance-window check. This is the origin's real gate.
    const v = verifyMandate(mandate, this.key);
    if (!v.valid) {
      return { httpStatus: 402, headers: {}, body: `payment required: ${v.reason ?? 'invalid proof'}` };
    }

    // Origin-side replay protection: the same real proof must not release
    // content twice.
    if (this.consumedNonce.has(mandate.nonce)) {
      return { httpStatus: 402, headers: {}, body: 'payment required: replayed proof' };
    }

    // Consume it, so a replay is refused next time.
    this.consumedNonce.add(mandate.nonce);

    return {
      httpStatus: 200,
      headers: { 'content-type': 'text/html; charset=utf-8' },
      body:
        '<html>real metered content — released only after a real, verified 402 proof</html>',
    };
  }

  /** How many distinct proofs have been released (== released twice-guarded). */
  get releasedCount(): number {
    return this.consumedNonce.size;
  }
}

/** Wire up the real rail + real origin + real budget, as production does. */
function make() {
  const key = makeSettlementKey(clock);
  const server = new SettlementServer({ key, clock });
  const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });
  const origin = new RealMeteredOrigin(key);
  const budget = new BudgetEngine({ policy: defaultPolicy, clock });
  const ledger = new AuditLedger({ clock });
  const broker = new Broker({ rail, budget, ledger, origin, clock });
  return { broker, server, rail, origin, ledger, key };
}

async function runOnce(fetchId = makeFetchId()) {
  const ctx = make();
  const outcome = await ctx.broker.fetch({ url: CONTENT_URL, fetchId });
  return { ...ctx, outcome };
}

describe('real 402 metered origin — 402 → settle → 200 round trip', () => {
  it('releases content after the rail's real Ed25519 proof, end to end', async () => {
    const { origin, server, ledger, outcome } = await runOnce();

    // The broker settled against the real backend (real nonce consumed once).
    expect(server.settledCount()).toBe(1);

    // The real origin verified the real signed proof and released exactly once.
    expect(origin.releasedCount).toBe(1);

    // Terminal outcome: fulfilled, with the settlement proven on the row.
    expect(outcome.status).toBe('fulfilled');
    expect(outcome.origin?.httpStatus).toBe(200);
    expect(outcome.settlementRef).toBeTruthy();
    expect(outcome.rail).toBe('self402');
    expect(outcome.price?.unitsMicros).toBe(PRICE);

    // One row recorded, and the audit reconciles clean (we paid, we can prove it).
    expect(ledger.entries.length).toBe(1);
    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(true);
    expect(rep.problems).toEqual([]);
  });

  it('a fulfilled fetch is only `finality: final` when the ledger reconciles', async () => {
    const { outcome, ledger } = await runOnce();

    // Same round trip as above, but asserting P2: the fulfilled outcome is
    // NOT merely "attempted" — it is `final` because reconcile() passed.
    expect(outcome.finality).toBe('final');

    // And a row that breaks reconciliation re-derives to `claimed`.
    // (A fulfilled row with no settlementRef makes reconcile().ok === false.)
    ledger.record({
      fetchId: 'poison',
      status: 'fulfilled',
      reason: 'injected to break reconciliation',
      origin: { url: 'https://bad.example/inject' },
      price: { unitsMicros: 100, currency: 'USD' },
      // intentionally no settlementRef
      tenantId: 'default',
      timestamps: { startedAt: clock.now(), completedAt: clock.now() },
    });

    // A NEW fetch on a ledger that can't reconcile is fulfilled by the origin,
    // but finality must be `claimed`, never `final` — we never bet real
    // settlement on an assumption.
    const ctx = make();
    const pctx = { ...ctx, ledger };
    const second = await pctx.broker.fetch({
      url: CONTENT_URL,
      fetchId: makeFetchId(),
    });
    expect(second.status).toBe('fulfilled'); // origin released the real proof
    expect(second.finality).toBe('claimed'); // ...but the ledger won't reconcile
    expect(reconcile(ledger.entries).ok).toBe(false);
  });
});

describe('real 402 metered origin — the 402 legs on real bytes', () => {
  it('rejects a forged proof whose signature does not verify (402)', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });
    const origin = new RealMeteredOrigin(key);

    // Mint the real signed mandate the broker would present.
    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const mandate = JSON.parse(auth.payload) as PaymentMandate;

    // Tamper the amount: the signature is over the original manifest, so this
    // mandate no longer verifies — a real origin refuses it with 402.
    const tampered: PaymentMandate = { ...mandate, amountMicros: mandate.amountMicros + 1 };
    const wire = encodeXPayment(tampered);

    const resp = await origin.fetch({
      url: CONTENT_URL,
      method: 'GET',
      headers: { 'x-payment': wire },
    });
    expect(resp.httpStatus).toBe(402);
    expect(resp.body).toContain('signature-mismatch');
  });

  it('rejects a replayed proof (402) — real origin-side nonce guard', async () => {
    const key = makeSettlementKey(clock);
    const server = new SettlementServer({ key, clock });
    const rail = makeSelf402Rail(server, { priceMicros: PRICE, clock });

    // Mint the real signed mandate.
    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const wire = auth.settlementHeaders['x-payment'];
    const mandate = decodeXPayment(wire);
    const req = { url: CONTENT_URL, method: 'GET', headers: { 'x-payment': wire } } as PaymentRequest;

    const origin = new RealMeteredOrigin(key);

    // First release: valid proof, consumed → 200.
    const first = await origin.fetch(req);
    expect(first.httpStatus).toBe(200);
    expect(origin.releasedCount).toBe(1);

    // Replay the exact same real proof on the wire → 402. The origin's nonce
    // guard refuses the duplicate real proof, on the same base64url envelope.
    const replay = await origin.fetch(req);
    expect(replay.httpStatus).toBe(402);
    expect(replay.body).toContain('replayed');
  });

  it('a real origin that cannot verify the backend key's proof demands payment', async () => {
    // A different settlement key than the rail's — a mismatched origin cannot
    // verify the broker's proof, so it must demand payment (402), as a real
    // origin whose facilitator key does not match would.
    const wrong = makeSettlementKey(clock);
    const origin = new RealMeteredOrigin(wrong);
    const { rail } = make();

    const quote = await rail.quote({ url: CONTENT_URL, method: 'GET', headers: {} });
    const auth = await rail.authorize({ url: CONTENT_URL, method: 'GET', headers: {} }, quote);
    const wire = auth.settlementHeaders['x-payment'];

    const resp = await origin.fetch({
      url: CONTENT_URL,
      method: 'GET',
      headers: { 'x-payment': wire },
    });
    expect(resp.httpStatus).toBe(402);
  });
});

describe('real 402 metered origin — over an actual HTTP socket', () => {
  it('POST /fetch returns 200 on a real metered release, then /audit reconciles', async () => {
    const { broker, ledger, origin } = make();

    // A tiny HTTP surface that funnels requests through the real handleFetch,
    // so the loop is proven on real bytes over a socket (not just in-process).
    const app = createServer((req, res) => {
      const chunks: Buffer[] = [];
      req.on('data', (c: Buffer) => chunks.push(c));
      req.on('end', async () => {
        try {
          const raw = Buffer.concat(chunks).toString('utf8');
          const { status, body } = await handleFetch(broker, raw);
          res.writeHead(status, { 'content-type': 'application/json' });
          res.end(JSON.stringify(body));
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          res.writeHead(500, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: 'server error', message }));
        }
      });
    });

    await new Promise<void>((resolve) => app.listen(0, resolve));
    const port = (app.address() as AddressInfo).port;

    try {
      const res = await new Promise<{ status: number; json: unknown }>((resolve, reject) => {
        const payload = JSON.stringify({ url: CONTENT_URL.toString(), fetchId: makeFetchId() });
        const req = request(
          { hostname: '127.0.0.1', port, path: '/fetch', method: 'POST', headers: { 'content-type': 'application/json' } },
          (resBody) => {
            const chunks: Buffer[] = [];
            resBody.on('data', (c: Buffer) => chunks.push(c));
            resBody.on('end', () => {
              try {
                resolve({ status: resBody.statusCode ?? 0, json: JSON.parse(Buffer.concat(chunks).toString('utf8')) });
              } catch (e) {
                reject(e as Error);
              }
            });
          },
        );
        req.on('error', reject);
        req.end(payload);
      });

      // 200 on the wire, fulfilled body, P2 finality, and the audit reconciles.
      expect(res.status).toBe(200);
      expect((res.json as { status: string }).status).toBe('fulfilled');
      expect((res.json as { finality: string }).finality).toBe('final');
      expect(origin.releasedCount).toBe(1);
      expect(reconcile(ledger.entries).ok).toBe(true);
    } finally {
      await new Promise<void>((resolve) => app.close(() => resolve()));
    }
  });
});
"}

