      tenantId: 'default',
      timestamps: { startedAt: clock.now(), completedAt: clock.now() },
    } as any);

    const rep1 = reconcile(ctx1.ledger.entries);
    console.log('AFTER POISON reconcile OK', rep1.ok, JSON.stringify(rep1.problems));

    const ctx2 = make();
    const pctx = { ...ctx2, ledger: ctx1.ledger };
    const second = await pctx.broker.fetch({ url: CONTENT_URL as any, fetchId: 'f2' });
    console.log('SECOND finality', second.finality);
    const rep2 = reconcile(pctx.ledger.entries);
    console.log('AFTER SECOND reconcile OK', rep2.ok);
    console.log('ENTRY COUNT', pctx.ledger.entries.length);
    console.log('POISON ROW', JSON.stringify(pctx.ledger.entries.find((e:any)=>e.fetchId==='poison')));
  });
});
